// Mandelbulb Skin - color only, ANIMATED. Runs INSIDE shadeSurface().
// The Mandelbulb iteration (z -> z^n + c in spherical coordinates, n = 8) run at
// every point of the surface: the object is dressed with the bulb's orbit-trap
// colors, as if it were cut out of it. The angles turn slowly with time, so the
// pattern flows over the surface.
// No displacement: one evaluation per pixel, cheap at any resolution.
// In scope: pModel, n_model, t. Dock colors: u_col1 = light, u_col2 = deep tone.

float ZOOM  = 0.92 * max(E, 0.05);     // slider E   // size of the bulb       [0.6 .. 2.5]
float POWER = 8.0 * max(F, 0.25);      // slider F   // power of the formula   [2 .. 16]
float SPIN  = 0.15;                    // how fast the angles turn (0 = still)
const int ITER = 8;

vec3 c3 = pModel * ZOOM;
vec3 zb = c3;
vec4 trap = vec4(1e9);
float r = length(zb);
float n = float(ITER);
for (int i = 0; i < ITER; i++) {
    r = length(zb);
    if (r > 2.0) { n = float(i); break; }
    float theta = acos(clamp(zb.z / max(r, 1e-6), -1.0, 1.0)) * POWER;
    float phi   = atan(zb.y, zb.x) * POWER + SPIN * t;
    float zr    = pow(r, POWER);
    zb = zr * vec3(sin(theta) * cos(phi), sin(theta) * sin(phi), cos(theta)) + c3;
    trap = min(trap, vec4(abs(zb), dot(zb, zb)));
}

// escaped points: smooth escape count (log-log), bands of the dock colors
float sn = n + 1.0 - log(max(log(max(r, 1.0001)), 1e-4)) / log(POWER);
float k  = clamp(sn / float(ITER), 0.0, 1.0);
vec3 col = mix(ubuf.u_col2, ubuf.u_col1, 0.25 + 0.75 * k);
col *= 0.75 + 0.25 * cos(2.4 * sn - 0.5 * t * SPIN * 4.0);
// points still bound after ITER steps are INSIDE the bulb: orbit-trap colors
if (n >= float(ITER)) {
    vec3 trapCol = 0.5 + 0.5 * cos(6.2832 * (vec3(0.0, 0.25, 0.5) + 1.5 * sqrt(trap.xyz)));
    col = mix(ubuf.u_col1 * 0.9, trapCol * ubuf.u_col1 + 0.2 * ubuf.u_col2, 0.6);
    col *= 0.55 + 0.45 * clamp(sqrt(trap.w), 0.0, 1.0);
}

textureCol = col;
